import{_ as t,o as n,c as r,a2 as i}from"./chunks/framework.Buc7gXeZ.js";const g=JSON.parse('{"title":"Ersten Flow bauen","description":"Schritt für Schritt einen Flow anlegen, konfigurieren, testen und aktivieren.","frontmatter":{"title":"Ersten Flow bauen","description":"Schritt für Schritt einen Flow anlegen, konfigurieren, testen und aktivieren."},"headers":[],"relativePath":"flows/ersten-flow-bauen.md","filePath":"flows/ersten-flow-bauen.md","lastUpdated":1786016533000}'),a={name:"flows/ersten-flow-bauen.md"};function s(l,e,o,d,h,u){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="ersten-flow-bauen" tabindex="-1">Ersten Flow bauen <a class="header-anchor" href="#ersten-flow-bauen" aria-label="Permalink to &quot;Ersten Flow bauen&quot;">​</a></h1><p>Diese Anleitung baut einen vollständigen Flow: Sobald jemand ein Anmeldeformular absendet, geht eine Bestätigungsmail raus und der Status im Grid wird gesetzt.</p><p><strong>Voraussetzung:</strong> ein Grid mit einem Feld vom Typ <em>E-Mail</em> und einem Feld vom Typ <em>Einzelauswahl</em> (etwa <code>Status</code> mit den Optionen <code>Neu</code> und <code>Bestätigt</code>), dazu ein <a href="/docs/formulare/formular-erstellen">Formular</a> darauf.</p><h2 id="_1-·-flow-anlegen" tabindex="-1">1 · Flow anlegen <a class="header-anchor" href="#_1-·-flow-anlegen" aria-label="Permalink to &quot;1 · Flow anlegen&quot;">​</a></h2><ol><li>Öffnen Sie in der Seitenleiste den Bereich <strong>Flows</strong>.</li><li>Klicken Sie auf <strong>Flow erstellen</strong>.</li><li>Der Flow heißt zunächst <em>Neuer Flow</em>. Benennen Sie ihn um — bei mehreren Flows zahlt sich das schnell aus.</li></ol><p>Sie landen im <strong>Editor</strong>, einer leeren Arbeitsfläche.</p><h2 id="_2-·-ausloser-wahlen" tabindex="-1">2 · Auslöser wählen <a class="header-anchor" href="#_2-·-ausloser-wahlen" aria-label="Permalink to &quot;2 · Auslöser wählen&quot;">​</a></h2><p>Der Editor fragt: <em>Wann soll der Flow starten?</em></p><ol><li>Öffnen Sie den Reiter <strong>Auslöser</strong>.</li><li>Wählen Sie <strong>Eintrag per Formular</strong> — <em>Neuer Eintrag per Formular hinzugefügt</em>.</li><li>Wählen Sie im Schritt das Grid und das Formular aus.</li></ol><p>Sie können den Schritt anklicken oder per Drag &amp; Drop auf die Fläche ziehen.</p><div class="tip custom-block"><p class="custom-block-title">Auslöser bestimmt, welche Daten zur Verfügung stehen</p><p>Die Wahl des Auslösers entscheidet, womit alle folgenden Schritte arbeiten können. <em>Eintrag per Formular</em> liefert den neu angelegten Eintrag mit allen Feldern — das ist die Grundlage für alles Weitere.</p><p>Nachträglich lässt sich der Auslöser nicht einfach austauschen, ohne die folgenden Schritte anzupassen. Überlegen Sie ihn sich also zuerst.</p></div><h2 id="_3-·-erste-aktion-e-mail-senden" tabindex="-1">3 · Erste Aktion: E-Mail senden <a class="header-anchor" href="#_3-·-erste-aktion-e-mail-senden" aria-label="Permalink to &quot;3 · Erste Aktion: E-Mail senden&quot;">​</a></h2><ol><li>Öffnen Sie den Reiter <strong>Aktionen</strong>.</li><li>Wählen Sie <strong>E-Mail</strong>.</li><li>Verbinden Sie den Auslöser mit der neuen Aktion, falls das nicht automatisch geschieht.</li><li>Klicken Sie die Aktion an, um sie zu konfigurieren.</li></ol><p>Im Feld <em>Empfänger</em> wollen Sie nicht eine feste Adresse, sondern die aus dem Eintrag. Nutzen Sie dafür <strong>Werte aus vorherigen Schritten verwenden</strong> und wählen Sie das E-Mail-Feld des Auslösers.</p><p>Betreff und Text füllen Sie genauso — feste Texte und Werte aus dem Eintrag lassen sich mischen.</p><div class="tip custom-block"><p class="custom-block-title">Feldwerte einfügen</p><p>In Textfeldern öffnet <strong>Strg + Leertaste</strong> die Auswahl der verfügbaren Grid-Felder. Der Editor blendet diesen Hinweis auch selbst ein.</p></div><h2 id="_4-·-zweite-aktion-eintrag-aktualisieren" tabindex="-1">4 · Zweite Aktion: Eintrag aktualisieren <a class="header-anchor" href="#_4-·-zweite-aktion-eintrag-aktualisieren" aria-label="Permalink to &quot;4 · Zweite Aktion: Eintrag aktualisieren&quot;">​</a></h2><ol><li>Wählen Sie im Reiter <strong>Aktionen</strong> den Schritt <strong>Eintrag aktualisieren</strong>.</li><li>Verbinden Sie ihn hinter die E-Mail-Aktion.</li><li>Als zu aktualisierenden Eintrag wählen Sie den Eintrag aus dem Auslöser.</li><li>Setzen Sie das Feld <code>Status</code> auf <code>Bestätigt</code>.</li></ol><p>Der Flow steht.</p><h2 id="_5-·-testen" tabindex="-1">5 · Testen <a class="header-anchor" href="#_5-·-testen" aria-label="Permalink to &quot;5 · Testen&quot;">​</a></h2><p><strong>Testen Sie, bevor Sie den Flow scharf schalten.</strong> Ein fehlerhafter Flow, der auf echte Formulareingaben reagiert, verschickt fehlerhafte Mails an echte Menschen.</p><p>Im Editor stehen mehrere Testarten zur Verfügung. Für diesen Fall passt <strong>Mit Daten aus dem Flow Formular</strong> — <em>Das Formular öffnen und mit übermittelten Daten testen</em>.</p><p>Alternativ: <strong>Flow testen</strong> verwendet die letzte Zeile des Grids.</p><p>Nach dem Test prüfen Sie im Reiter <strong>Verlauf</strong>, ob der Durchlauf den Status <em>Fertig</em> hat. Bei <em>Fehler</em> öffnen Sie ihn und sehen über <strong>Fehlerdetails anzeigen</strong>, woran es lag.</p><p>→ <a href="/docs/flows/testen">Flows testen</a></p><h2 id="_6-·-in-betrieb-nehmen" tabindex="-1">6 · In Betrieb nehmen <a class="header-anchor" href="#_6-·-in-betrieb-nehmen" aria-label="Permalink to &quot;6 · In Betrieb nehmen&quot;">​</a></h2><p>Läuft der Test sauber durch, ist der Flow einsatzbereit. Er reagiert ab jetzt auf jede echte Formulareingabe.</p><div class="warning custom-block"><p class="custom-block-title">Erst mit einer echten Eingabe prüfen</p><p>Senden Sie das Formular einmal selbst ab, mit Ihrer eigenen Adresse. Ein Testlauf im Editor und ein echter Durchlauf verhalten sich nicht immer identisch — insbesondere bei Feldern, die nur im Formular gesetzt werden.</p></div><h2 id="arbeiten-im-editor" tabindex="-1">Arbeiten im Editor <a class="header-anchor" href="#arbeiten-im-editor" aria-label="Permalink to &quot;Arbeiten im Editor&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Werkzeug</th><th>Zweck</th></tr></thead><tbody><tr><td><strong>Auf alle Knoten zentrieren</strong></td><td>Holt alle Schritte ins Bild</td></tr><tr><td><strong>Knoten automatisch anordnen</strong></td><td>Räumt die Anordnung auf</td></tr><tr><td><strong>Minimap ein-/ausblenden</strong></td><td>Übersicht bei großen Flows</td></tr></tbody></table><p>Das Menü an einem Schritt bietet <strong>Umbenennen</strong>, <strong>Konfigurieren</strong>, <strong>Verbindung hinzufügen</strong> und <strong>Löschen</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Schritte umbenennen</p><p>Standardnamen wie „E-Mail&quot; sagen bei fünf Mail-Schritten nichts mehr. Benennen Sie Schritte nach ihrer Aufgabe — „Bestätigung an Teilnehmer&quot;, „Info an Team&quot;. Das zahlt sich in der Fehlersuche aus.</p></div><h2 id="typische-anfangerfehler" tabindex="-1">Typische Anfängerfehler <a class="header-anchor" href="#typische-anfangerfehler" aria-label="Permalink to &quot;Typische Anfängerfehler&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Ursache</th></tr></thead><tbody><tr><td>Flow startet nicht</td><td>Kein Auslöser gesetzt, oder der Auslöser zeigt auf ein anderes Grid oder Formular</td></tr><tr><td>Flow startet, tut aber nichts</td><td>Die Schritte sind nicht miteinander verbunden</td></tr><tr><td>E-Mail geht an niemanden</td><td>Im Empfängerfeld steht ein fester Text statt eines Feldwerts</td></tr><tr><td>Aktualisierung greift nicht</td><td>Der Schritt aktualisiert nicht den Eintrag aus dem Auslöser</td></tr><tr><td><em>Flow hat noch Fehler</em></td><td>Ein Schritt ist unvollständig konfiguriert</td></tr></tbody></table><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/docs/flows/trigger">Trigger</a></li><li><a href="/docs/flows/aktionen">Aktionen</a></li><li><a href="/docs/flows/daten-zwischen-schritten">Daten zwischen Schritten</a></li><li><a href="/docs/flows/testen">Flows testen</a></li></ul>',36)])])}const m=t(a,[["render",s]]);export{g as __pageData,m as default};
